const DEDUCTIBLE = 100;
const CAP_FACTOR = 2;
const HALF_REIMBURSEMENT_ENCHANTMENT = 8;

export class Policy {
  remainingCap: number;

  constructor(private readonly items: Item[]) {
    this.remainingCap = CAP_FACTOR * insuranceSum(items);
  }

  claim(damages: Damage[]): ClaimResult {
